import React, { useState, useEffect } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { customerService } from '../services/customerService';
import { billingService } from '../services/billingService';
import { paymentService } from '../services/paymentService';
import {
  Box,
  Paper,
  Typography,
  TextField,
  Button,
  InputAdornment,
  Grid,
  Card,
  CardContent,
  Chip,
  Container,
  CircularProgress,
  IconButton,
  Alert,
  Stack,
  Tabs,
  Tab,
  Divider,
  useTheme,
  Avatar,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  useMediaQuery,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Checkbox
} from '@mui/material';
import {
  ArrowBack as ArrowBackIcon,
  Search as SearchIcon,
  WaterDrop as WaterIcon,
  Person as PersonIcon,
  LocationOn as LocationOnIcon,
  Percent as PercentIcon,
  CalendarMonth as CalendarIcon,
  Opacity as OpacityIcon,
  AttachMoney as AttachMoneyIcon,
  Warning as WarningIcon,
  LocalOffer as TagIcon,
  ReceiptLong as ReceiptIcon,
  History as HistoryIcon,
  CheckCircle as CheckCircleIcon,
  AccessTime as AccessTimeIcon
} from '@mui/icons-material';

const CheckWaterBills = () => {
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const [customerId, setCustomerId] = useState('');
  const [loading, setLoading] = useState(false);
  const [customer, setCustomer] = useState(null);
  const [unpaidBills, setUnpaidBills] = useState([]);
  const [paymentHistory, setPaymentHistory] = useState([]);
  const [error, setError] = useState('');
  const [searched, setSearched] = useState(false);
  const [activeTab, setActiveTab] = useState(0);
  const [surchargeSettings, setSurchargeSettings] = useState(null);
  const [selectedBillIds, setSelectedBillIds] = useState([]);
  const [onlinePaymentDialogOpen, setOnlinePaymentDialogOpen] = useState(false);
  const [onlinePaymentSession, setOnlinePaymentSession] = useState(null);
  const [onlinePaymentLoading, setOnlinePaymentLoading] = useState(false);
  const [onlinePaymentError, setOnlinePaymentError] = useState('');

  // Fetch surcharge settings on component mount
  useEffect(() => {
    const fetchSettings = async () => {
      const result = await paymentService.getSurchargeSettings();
      if (result.success && result.data) {
        setSurchargeSettings(result.data);
      }
    };
    fetchSettings();
  }, []);

  useEffect(() => {
    const stored = localStorage.getItem('paymongoLastSession');
    if (!stored) return;

    let parsed;
    try {
      parsed = JSON.parse(stored);
    } catch {
      localStorage.removeItem('paymongoLastSession');
      return;
    }

    const { checkoutSessionId, customerId: storedCustomerId, billIds } = parsed || {};

    if (
      !checkoutSessionId ||
      !storedCustomerId ||
      !Array.isArray(billIds) ||
      billIds.length === 0
    ) {
      localStorage.removeItem('paymongoLastSession');
      return;
    }

    const confirmPayment = async () => {
      const result = await paymentService.confirmOnlinePayment({
        checkoutSessionId,
        customerId: storedCustomerId,
        billIds
      });

      localStorage.removeItem('paymongoLastSession');

      if (
        result &&
        result.success &&
        result.data &&
        result.data.success &&
        result.data.status === 'paid'
      ) {
        setCustomerId(storedCustomerId);
        setActiveTab(1);
        handleSearch(null, storedCustomerId);
      }
    };

    confirmPayment();
  }, []);

  // Helper function to round to 2 decimals
  const roundTo2 = (num) => {
    return Math.round(num * 100) / 100;
  };

  // Calculate surcharges and discounts for bills
  const calculateBillsWithSurcharge = (bills, customer) => {
    return bills.map(bill => {
      const surchargeInfo = surchargeSettings
        ? paymentService.calculateSurcharge(bill, surchargeSettings)
        : null;
      
      // Calculate discount from customer discount percentage
      const basicAmount = roundTo2(parseFloat(bill.basicamount || 0));
      
      // Priority: bill's stored discount > customer discount percentage
      let calculatedDiscountAmount = 0;
      if (bill.discountamount && parseFloat(bill.discountamount) > 0) {
        // Use stored discount from bill
        calculatedDiscountAmount = roundTo2(parseFloat(bill.discountamount));
      } else if (customer && customer.discount) {
        // Calculate from customer discount percentage
        const customerDiscountPercent = parseFloat(customer.discount);
        calculatedDiscountAmount = roundTo2((basicAmount * customerDiscountPercent) / 100);
      }
      
      // Calculate surcharge amount
      const surchargeAmount = roundTo2(surchargeInfo ? surchargeInfo.surchargeAmount : parseFloat(bill.surchargeamount || 0));
      
      // Calculate total: basic + surcharge - discount
      const totalWithSurcharge = roundTo2(basicAmount + surchargeAmount - calculatedDiscountAmount);
      
      return {
        ...bill,
        calculatedSurchargeAmount: surchargeAmount,
        calculatedDiscountAmount,
        calculatedTotal: totalWithSurcharge
      };
    });
  };

  useEffect(() => {
    const idFromQuery = searchParams.get('customerId');
    if (idFromQuery) {
      setCustomerId(idFromQuery);
      handleSearch(null, idFromQuery);
    }
  }, []);

  const handleSearch = async (e, overrideId) => {
    if (e && e.preventDefault) {
      e.preventDefault();
    }

    const idToUse = (overrideId ?? customerId).trim();

    if (!idToUse) {
      setError('Please enter a Customer ID');
      return;
    }

    setSearchParams({ customerId: idToUse });

    setLoading(true);
    setError('');
    setSearched(true);
    setCustomer(null);
    setUnpaidBills([]);
    setPaymentHistory([]);

    try {
      // Fetch customer details
      const customerResponse = await customerService.getCustomerById(idToUse);
      
      if (!customerResponse || !customerResponse.success || !customerResponse.data) {
        setError('Customer ID not found. Please check and try again.');
        setLoading(false);
        return;
      }

      setCustomer(customerResponse.data);

      // Fetch unpaid bills
      const billsResponse = await billingService.getCustomerBills(idToUse);
      if (billsResponse.success) {
        const unpaid = billsResponse.data.filter(bill => bill.paymentstatus === 'Unpaid');
        // Calculate surcharges and discounts
        const calculatedUnpaid = calculateBillsWithSurcharge(unpaid, customerResponse.data);
        setUnpaidBills(calculatedUnpaid);
      }

      // Fetch payment history (paid bills)
      const paymentsResponse = await paymentService.getPaymentHistory(idToUse);
      if (paymentsResponse.success) {
        setPaymentHistory(paymentsResponse.data);
      }

    } catch (err) {
      console.error('Error fetching data:', err);
      setError('An error occurred while fetching data. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const formatCurrency = (amount) => {
    return new Intl.NumberFormat('en-PH', {
      style: 'currency',
      currency: 'PHP'
    }).format(amount || 0);
  };

  const formatBillingMonth = (dateString) => {
    if (!dateString) return 'N/A';
    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', { 
      year: 'numeric', 
      month: 'long'
    });
  };

  const handleTabChange = (event, newValue) => {
    setActiveTab(newValue);
  };

  const selectedBills = unpaidBills.filter((bill) =>
    selectedBillIds.includes(bill.billid)
  );

  const selectedTotal = selectedBills.reduce(
    (sum, bill) => sum + (bill.calculatedTotal || 0),
    0
  );

  const billsForTotals = selectedBillIds.length > 0 ? selectedBills : unpaidBills;

  const totalOutstanding = billsForTotals.reduce(
    (sum, bill) => sum + (bill.calculatedTotal || 0),
    0
  );

  const totalDiscount = billsForTotals.reduce(
    (sum, bill) => sum + (bill.calculatedDiscountAmount || 0),
    0
  );

  const handleToggleBillSelection = (billId) => {
    setSelectedBillIds((prev) =>
      prev.includes(billId) ? prev.filter((id) => id !== billId) : [...prev, billId]
    );
  };

  const handleToggleSelectAll = () => {
    if (selectedBillIds.length === unpaidBills.length) {
      setSelectedBillIds([]);
    } else {
      setSelectedBillIds(unpaidBills.map((bill) => bill.billid));
    }
  };

  const handleStartOnlinePayment = async () => {
    if (!customer || selectedBillIds.length === 0) return;

    setOnlinePaymentLoading(true);
    setOnlinePaymentError('');

    try {
      const amountToPay = Math.max(
        0,
        selectedTotal - (customer.credit_balance || 0)
      );

      const result = await paymentService.createQrphPaymentSession({
        customerId: customer.customerid,
        billIds: selectedBillIds,
        amount: amountToPay,
        description: `Water bills payment for ${customer.customerid}`
      });

      if (!result.success) {
        setOnlinePaymentError(
          result.error || 'Failed to start online payment. Please try again.'
        );
        return;
      }
      
      const session = result.data;

      if (session && session.checkoutUrl) {
        if (session.checkoutSessionId) {
          const sessionInfo = {
            checkoutSessionId: session.checkoutSessionId,
            customerId: customer.customerid,
            billIds: selectedBillIds
          };
          localStorage.setItem('paymongoLastSession', JSON.stringify(sessionInfo));
        }
        window.location.href = session.checkoutUrl;
        return;
      }

      setOnlinePaymentSession(session);
      setOnlinePaymentDialogOpen(true);
    } catch (err) {
      setOnlinePaymentError(
        err.message || 'Failed to start online payment. Please try again.'
      );
    } finally {
      setOnlinePaymentLoading(false);
    }
  };

  return (
    <Box sx={{ minHeight: '100vh', bgcolor: '#f8fafc', py: { xs: 3, md: 6 } }}>
      <Container maxWidth="md">
        <Paper
          elevation={3}
          sx={{
            p: { xs: 2.5, md: 3.5 },
            mb: 4,
            borderRadius: 3,
            border: '1px solid',
            borderColor: 'divider',
            bgcolor: 'background.paper'
          }}
        >
          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
            <Button
              startIcon={<ArrowBackIcon />}
              onClick={() => navigate('/')}
              size="small"
            >
              Back
            </Button>
            <WaterIcon color="primary" sx={{ fontSize: 32 }} />
          </Box>

          <Box sx={{ mb: 3 }}>
            <Typography variant="h5" fontWeight="bold" color="text.primary">
              Check Water Bills
            </Typography>
            <Typography variant="body2" color="text.secondary">
              Enter your Customer ID to view unpaid bills and recent payments.
            </Typography>
          </Box>

          <form onSubmit={handleSearch}>
            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2}>
              <TextField
                fullWidth
                placeholder="Enter Customer ID (e.g., CUST-001)"
                value={customerId}
                onChange={(e) => setCustomerId(e.target.value)}
                disabled={loading}
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <SearchIcon color="action" />
                    </InputAdornment>
                  ),
                }}
              />
              <Button
                type="submit"
                variant="contained"
                size="medium"
                disabled={loading}
                startIcon={loading ? <CircularProgress size={20} color="inherit" /> : <SearchIcon />}
                sx={{ px: 3, minWidth: { xs: '100%', sm: 140 } }}
              >
                {loading ? 'Searching...' : 'Search'}
              </Button>
            </Stack>
          </form>

          {error && (
            <Alert severity="error" sx={{ mt: 2 }}>
              {error}
            </Alert>
          )}
        </Paper>

        {/* Results Section */}
        {searched && !loading && customer && (
          <Box>
            <Card
              sx={{
                mb: 3,
                borderRadius: 3,
                border: '1px solid',
                borderColor: 'divider',
                boxShadow: 1
              }}
            >
              <CardContent>
                <Stack direction="row" spacing={2} alignItems="center">
                  <Avatar sx={{ bgcolor: 'primary.light', color: 'primary.main', width: 48, height: 48 }}>
                    <PersonIcon />
                  </Avatar>
                  <Box sx={{ flexGrow: 1, minWidth: 0 }}>
                    <Typography variant="h6" fontWeight="bold" noWrap>
                      {customer.name}
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      ID: {customer.customerid}
                    </Typography>
                    {customer.type && (
                      <Typography variant="body2" color="text.secondary">
                        {customer.type}
                      </Typography>
                    )}
                    {customer.barangay && (
                      <Typography variant="body2" color="text.secondary">
                        Barangay: {customer.barangay}
                      </Typography>
                    )}
                  </Box>
                  <Chip
                    label={customer.status || 'Active'}
                    size="small"
                    color={customer.status === 'Active' ? 'success' : 'error'}
                  />
                </Stack>
              </CardContent>
            </Card>

            {/* Tabs */}
            <Paper sx={{ borderRadius: 2 }}>
              <Box sx={{ borderBottom: 1, borderColor: 'divider' }}>
                <Tabs value={activeTab} onChange={handleTabChange}>
                  <Tab 
                    label={
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        <WarningIcon color={activeTab === 0 ? 'primary' : 'action'} />
                        Unpaid Bills
                        {unpaidBills.length > 0 && (
                          <Chip label={unpaidBills.length} size="small" color="error" />
                        )}
                      </Box>
                    } 
                  />
                  <Tab 
                    label={
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        <HistoryIcon color={activeTab === 1 ? 'primary' : 'action'} />
                        Payment History
                      </Box>
                    } 
                  />
                </Tabs>
              </Box>

              <Box sx={{ p: 3, pb: isMobile ? 10 : 3 }}>
                {activeTab === 0 && (
                  <>
                    {unpaidBills.length === 0 ? (
                      <Box sx={{ textAlign: 'center', py: 4 }}>
                        <CheckCircleIcon color="success" sx={{ fontSize: 60, mb: 2 }} />
                        <Typography variant="h6">No unpaid bills</Typography>
                        <Typography color="text.secondary">All bills are settled</Typography>
                      </Box>
                    ) : (
                      <>
                        {isMobile ? (
                          <Stack spacing={1.5}>
                            {unpaidBills.map((bill) => (
                              <Card key={bill.billid} variant="outlined">
                                <CardContent sx={{ py: 1.5, '&:last-child': { pb: 1.5 } }}>
                                  <Box
                                    sx={{
                                      display: 'flex',
                                      justifyContent: 'space-between',
                                      alignItems: 'center',
                                      mb: 0.5
                                    }}
                                  >
                                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                      <Checkbox
                                        size="small"
                                        color="primary"
                                        checked={selectedBillIds.includes(bill.billid)}
                                        onChange={() => handleToggleBillSelection(bill.billid)}
                                      />
                                      <Typography variant="body2" fontWeight="medium">
                                        {formatBillingMonth(bill.billedmonth)}
                                      </Typography>
                                    </Box>
                                    <Typography variant="body2" fontWeight="bold" color="primary.main">
                                      {formatCurrency(bill.calculatedTotal)}
                                    </Typography>
                                  </Box>
                                  <Typography variant="body2" color="text.secondary">
                                    {bill.previousreading} - {bill.currentreading} = {bill.consumption} m³
                                  </Typography>
                                  <Typography variant="caption" color="text.secondary">
                                    Basic {formatCurrency(bill.basicamount)}
                                  </Typography>
                                  {(bill.calculatedSurchargeAmount > 0 ||
                                    bill.calculatedDiscountAmount > 0) && (
                                    <Typography variant="caption" color="text.secondary" sx={{ display: 'block' }}>
                                      Adj:{' '}
                                      {bill.calculatedSurchargeAmount > 0 &&
                                        `+${formatCurrency(bill.calculatedSurchargeAmount)} `}
                                      {bill.calculatedDiscountAmount > 0 &&
                                        `-${formatCurrency(bill.calculatedDiscountAmount)}`}
                                    </Typography>
                                  )}
                                </CardContent>
                              </Card>
                            ))}
                          </Stack>
                        ) : (
                          <TableContainer
                            component={Paper}
                            variant="outlined"
                            sx={{ borderRadius: 2, maxHeight: 420, overflowX: 'auto' }}
                          >
                            <Table size="small" stickyHeader sx={{ minWidth: 600 }}>
                              <TableHead>
                                <TableRow>
                                  <TableCell padding="checkbox">
                                    <Checkbox
                                      color="primary"
                                      checked={
                                        unpaidBills.length > 0 &&
                                        selectedBillIds.length === unpaidBills.length
                                      }
                                      indeterminate={
                                        selectedBillIds.length > 0 &&
                                        selectedBillIds.length < unpaidBills.length
                                      }
                                      onChange={handleToggleSelectAll}
                                    />
                                  </TableCell>
                                  <TableCell>Billing Period</TableCell>
                                  <TableCell align="right">Consumption</TableCell>
                                  <TableCell align="right">Basic</TableCell>
                                  <TableCell align="right">Adj. (SC/ Disc)</TableCell>
                                  <TableCell align="right">Total</TableCell>
                                </TableRow>
                              </TableHead>
                              <TableBody>
                                {unpaidBills.map((bill) => (
                                  <TableRow key={bill.billid} hover>
                                    <TableCell padding="checkbox">
                                      <Checkbox
                                        color="primary"
                                        checked={selectedBillIds.includes(bill.billid)}
                                        onChange={() => handleToggleBillSelection(bill.billid)}
                                      />
                                    </TableCell>
                                    <TableCell>
                                      <Typography variant="body2" fontWeight="medium">
                                        {formatBillingMonth(bill.billedmonth)}
                                      </Typography>
                                    </TableCell>
                                    <TableCell align="right">
                                      <Typography variant="body2">
                                        {bill.previousreading} - {bill.currentreading} = {bill.consumption} m³
                                      </Typography>
                                    </TableCell>
                                    <TableCell align="right">
                                      <Typography variant="body2">
                                        {formatCurrency(bill.basicamount)}
                                      </Typography>
                                    </TableCell>
                                    <TableCell align="right">
                                      {bill.calculatedSurchargeAmount > 0 && (
                                        <Typography variant="body2" color="error.main">
                                          +{formatCurrency(bill.calculatedSurchargeAmount)}
                                        </Typography>
                                      )}
                                      {bill.calculatedDiscountAmount > 0 && (
                                        <Typography variant="body2" color="success.main">
                                          -{formatCurrency(bill.calculatedDiscountAmount)}
                                        </Typography>
                                      )}
                                      {bill.calculatedSurchargeAmount <= 0 &&
                                        bill.calculatedDiscountAmount <= 0 && (
                                          <Typography variant="body2" color="text.secondary">
                                            —
                                          </Typography>
                                        )}
                                    </TableCell>
                                    <TableCell align="right">
                                      <Typography
                                        variant="body2"
                                        fontWeight="bold"
                                        color="primary.main"
                                      >
                                        {formatCurrency(bill.calculatedTotal)}
                                      </Typography>
                                    </TableCell>
                                  </TableRow>
                                ))}
                              </TableBody>
                            </Table>
                          </TableContainer>
                        )}
                        <Box
                          sx={{
                            mt: isMobile ? 0 : 3,
                            p: 2,
                            bgcolor: 'primary.light',
                            color: 'primary.contrastText',
                            borderRadius: 2,
                            position: isMobile ? 'fixed' : 'static',
                            left: isMobile ? 0 : 'auto',
                            right: isMobile ? 0 : 'auto',
                            bottom: isMobile ? 0 : 'auto',
                            width: isMobile ? '100%' : 'auto',
                            boxShadow: isMobile ? 6 : 'none',
                            zIndex: isMobile ? 1200 : 'auto'
                          }}
                        >
                          <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                            <Box>
                              <Typography variant="subtitle1" fontWeight="bold">
                                {customer.credit_balance > 0 ? 'Net Outstanding' : 'Total Outstanding'}
                              </Typography>
                              {(customer.credit_balance > 0 || totalDiscount > 0) && (
                                <Typography variant="caption" sx={{ mt: 0.25, display: 'block', opacity: 0.9 }}>
                                  {customer.credit_balance > 0 && `Credits: ${formatCurrency(customer.credit_balance)}`}
                                  {customer.credit_balance > 0 && totalDiscount > 0 && ' · '}
                                  {totalDiscount > 0 && `Discounts: ${formatCurrency(totalDiscount)}`}
                                </Typography>
                              )}
                              {selectedBillIds.length > 0 && (
                                <Typography variant="caption" sx={{ mt: 0.25, display: 'block', opacity: 0.9 }}>
                                  Selected: {formatCurrency(selectedTotal)}
                                </Typography>
                              )}
                            </Box>
                            <Typography variant="h5" fontWeight="bold">
                              {customer.credit_balance > 0
                                ? formatCurrency(Math.max(0, totalOutstanding - customer.credit_balance))
                                : formatCurrency(totalOutstanding)}
                            </Typography>
                          </Box>
                          <Box
                            sx={{
                              mt: 1.5,
                              display: 'flex',
                              flexDirection: isMobile ? 'column' : 'row',
                              gap: 1
                            }}
                          >
                            <Button
                              variant="contained"
                              color="success"
                              fullWidth={isMobile}
                              disabled={selectedBillIds.length === 0 || onlinePaymentLoading}
                              onClick={handleStartOnlinePayment}
                            >
                              {onlinePaymentLoading
                                ? 'Starting payment...'
                                : selectedBillIds.length > 0
                                ? `Pay Online (${selectedBillIds.length})`
                                : 'Pay Online'}
                            </Button>
                          </Box>
                          {onlinePaymentError && (
                            <Typography
                              variant="caption"
                              sx={{ mt: 0.5, display: 'block' }}
                              color="error.contrastText"
                            >
                              {onlinePaymentError}
                            </Typography>
                          )}
                        </Box>
                      </>
                    )}
                  </>
                )}

                {activeTab === 1 && (
                  <>
                    {paymentHistory.length === 0 ? (
                      <Box sx={{ textAlign: 'center', py: 4 }}>
                        <HistoryIcon color="action" sx={{ fontSize: 60, mb: 2 }} />
                        <Typography variant="h6" color="text.secondary">No payment history</Typography>
                      </Box>
                    ) : isMobile ? (
                      <Stack spacing={1.5}>
                        {paymentHistory.slice(0, 10).map((bill) => (
                          <Card key={bill.billid} variant="outlined">
                            <CardContent sx={{ py: 1.5, '&:last-child': { pb: 1.5 } }}>
                              <Box
                                sx={{
                                  display: 'flex',
                                  justifyContent: 'space-between',
                                  alignItems: 'baseline',
                                  mb: 0.5
                                }}
                              >
                                <Typography variant="body2" fontWeight="medium">
                                  {formatBillingMonth(bill.billedmonth)}
                                </Typography>
                                <Typography variant="body2" fontWeight="bold" color="success.main">
                                  {formatCurrency(bill.totalbillamount)}
                                </Typography>
                              </Box>
                              <Typography variant="body2" color="text.secondary">
                                {bill.consumption} m³
                              </Typography>
                              <Typography variant="caption" color="text.secondary">
                                Basic {formatCurrency(bill.basicamount)}
                              </Typography>
                              {(bill.surchargeamount > 0 || bill.discountamount > 0) && (
                                <Typography variant="caption" color="text.secondary" sx={{ display: 'block' }}>
                                  Adj:{' '}
                                  {bill.surchargeamount > 0 &&
                                    `+${formatCurrency(bill.surchargeamount)} `}
                                  {bill.discountamount > 0 &&
                                    `-${formatCurrency(bill.discountamount)}`}
                                </Typography>
                              )}
                              <Typography variant="caption" color="success.main" sx={{ display: 'block', mt: 0.5 }}>
                                Paid
                              </Typography>
                            </CardContent>
                          </Card>
                        ))}
                      </Stack>
                    ) : (
                      <Stack spacing={2}>
                        {paymentHistory.slice(0, 10).map((bill) => (
                          <Card key={bill.billid} variant="outlined" sx={{ bgcolor: 'grey.50' }}>
                            <CardContent>
                              <Grid container spacing={2} alignItems="center">
                                <Grid item xs={12} sm={6} md={3}>
                                  <Typography variant="caption" color="text.secondary" display="flex" alignItems="center" gap={0.5}>
                                    <CalendarIcon fontSize="small" /> Billing Period
                                  </Typography>
                                  <Typography variant="subtitle1" fontWeight="medium">
                                    {formatBillingMonth(bill.billedmonth)}
                                  </Typography>
                                </Grid>
                                <Grid item xs={12} sm={6} md={3}>
                                  <Typography variant="caption" color="text.secondary" display="flex" alignItems="center" gap={0.5}>
                                    <OpacityIcon fontSize="small" /> Consumption
                                  </Typography>
                                  <Typography variant="body1">
                                    {bill.consumption} m³
                                  </Typography>
                                </Grid>
                                <Grid item xs={12} sm={6} md={4}>
                                  <Typography variant="caption" color="text.secondary" display="block">Amount Breakdown</Typography>
                                  <Typography variant="body2">
                                    Basic: {formatCurrency(bill.basicamount)} 
                                    {bill.surchargeamount > 0 && ` + Surcharge: ${formatCurrency(bill.surchargeamount)}`}
                                    {bill.discountamount > 0 && ` - Discount: ${formatCurrency(bill.discountamount)}`}
                                  </Typography>
                                </Grid>
                                <Grid item xs={12} sm={6} md={2} sx={{ textAlign: 'right' }}>
                                  <Typography variant="h6" color="success.main" fontWeight="bold">
                                    {formatCurrency(bill.totalbillamount)}
                                  </Typography>
                                  <Chip 
                                    icon={<CheckCircleIcon />} 
                                    label="Paid" 
                                    color="success" 
                                    size="small" 
                                  />
                                </Grid>
                              </Grid>
                            </CardContent>
                          </Card>
                        ))}
                      </Stack>
                    )}
                  </>
                )}
              </Box>
            </Paper>
          </Box>
        )}

        {/* No Results */}
        {searched && !loading && !customer && !error && (
          <Box sx={{ textAlign: 'center', py: 8 }}>
            <SearchIcon sx={{ fontSize: 60, color: 'text.secondary', mb: 2 }} />
            <Typography variant="h6" color="text.secondary">No customer found</Typography>
            <Typography color="text.secondary">Please check the Customer ID and try again</Typography>
          </Box>
        )}

        <Dialog
          open={onlinePaymentDialogOpen}
          onClose={() => {
            setOnlinePaymentDialogOpen(false);
            setOnlinePaymentSession(null);
          }}
          fullWidth
          maxWidth="xs"
        >
          <DialogTitle>Pay Online via PayMongo</DialogTitle>
          <DialogContent dividers>
            {onlinePaymentSession && (
              <>
                <Typography variant="body2" sx={{ mb: 2 }}>
                  You will be redirected to PayMongo to complete your payment.
                </Typography>
              </>
            )}
            {!onlinePaymentSession && (
              <Typography variant="body2">
                Payment session created. Please follow the instructions in the PayMongo checkout page.
              </Typography>
            )}
          </DialogContent>
          <DialogActions>
            <Button onClick={() => setOnlinePaymentDialogOpen(false)}>
              Close
            </Button>
          </DialogActions>
        </Dialog>
      </Container>
    </Box>
  );
};

export default CheckWaterBills;
