import { supabase } from '../supabaseClient'

export const reportService = {
  // Get unique barangays for filters
  async getBarangays() {
    try {
      const { data, error } = await supabase
        .from('customers')
        .select('barangay')
        .not('barangay', 'is', null)
        .limit(10000)

      if (error) throw error

      const unique = [...new Set(data.map(c => c.barangay))]
      return { success: true, data: unique.sort() }
    } catch (error) {
      return { success: false, error: error.message, data: [] }
    }
  },
  // Get customers with unusual usage across all billing history
  async getUsageAnomalies(threshold = 10, paymentStatus = 'All') {
    try {
      let baseQuery = supabase
        .from('bills')
        .select('customerid, billedmonth, consumption, paymentstatus')
        .order('customerid', { ascending: true })
        .order('billedmonth', { ascending: true })

      if (paymentStatus === 'Paid' || paymentStatus === 'Unpaid') {
        baseQuery = baseQuery.eq('paymentstatus', paymentStatus)
      }

      let allBills = []
      let start = 0
      const batchSize = 1000
      let hasMore = true

      while (hasMore) {
        const { data: batch, error } = await baseQuery.range(start, start + batchSize - 1)
        if (error) throw error

        if (batch && batch.length > 0) {
          allBills = allBills.concat(batch)
          if (batch.length < batchSize) {
            hasMore = false
          } else {
            start += batchSize
          }
        } else {
          hasMore = false
        }
      }

      if (allBills.length === 0) {
        return { success: true, data: [] }
      }

      const byCustomer = {}

      allBills.forEach(bill => {
        const customerid = bill.customerid
        if (!customerid) return

        if (!byCustomer[customerid]) {
          byCustomer[customerid] = []
        }

        const cons = parseFloat(bill.consumption || 0)
        byCustomer[customerid].push({
          month: bill.billedmonth,
          consumption: cons
        })
      })

      const anomalies = []

      Object.entries(byCustomer).forEach(([customerid, bills]) => {
        if (!bills || bills.length < 2) {
          return
        }

        const total = bills.reduce((sum, b) => sum + b.consumption, 0)
        const count = bills.length

        bills.forEach(bill => {
          const historyCount = count - 1
          if (historyCount <= 0) return

          const historyTotal = total - bill.consumption
          const avgHistory = historyTotal / historyCount
          const diff = bill.consumption - avgHistory

          if (diff >= threshold) {
            anomalies.push({
              customerid,
              avgHistory,
              current: bill.consumption,
              diff,
              month: bill.month
            })
          }
        })
      })

      if (anomalies.length === 0) {
        return { success: true, data: [] }
      }

      // Keep only the strongest anomaly (largest diff) per customer
      const bestByCustomer = {}
      anomalies.forEach(a => {
        const existing = bestByCustomer[a.customerid]
        if (!existing || a.diff > existing.diff) {
          bestByCustomer[a.customerid] = a
        }
      })

      const bestAnomalies = Object.values(bestByCustomer)

      const customerIds = bestAnomalies.map(a => a.customerid)

      const { data: customers, error: customerError } = await supabase
        .from('customers')
        .select('customerid, name, address, barangay, type, status')
        .in('customerid', customerIds)

      if (customerError) throw customerError

      const customerMap = {}
      if (customers) {
        customers.forEach(c => {
          customerMap[c.customerid] = c
        })
      }

      const result = bestAnomalies.map(a => {
        const customer = customerMap[a.customerid] || {}
        return {
          customerid: a.customerid,
          name: customer.name || 'Unknown',
          address: customer.address || '',
          barangay: customer.barangay || '',
          type: customer.type || '',
          status: customer.status || '',
          month: a.month,
          currentConsumption: a.current,
          averageHistoryConsumption: a.avgHistory,
          difference: a.diff
        }
      })

      return {
        success: true,
        data: result.sort((a, b) => b.difference - a.difference)
      }
    } catch (error) {
      console.error('Error getting usage anomalies:', error)
      return { success: false, error: error.message, data: [] }
    }
  },

  // Get unique customer types
  async getCustomerTypes() {
    try {
      const { data, error } = await supabase
        .from('customers')
        .select('type')
        .not('type', 'is', null)
        .limit(10000)

      if (error) throw error

      const unique = [...new Set(data.map(c => c.type))]
      return { success: true, data: unique.sort() }
    } catch (error) {
      return { success: false, error: error.message, data: [] }
    }
  },

  // Aging Report - Accounts Receivable by age
  async getAgingReport() {
    try {
      const { data, error } = await supabase
        .from('bills')
        .select('billid, customerid, billedmonth, totalbillamount')
        .eq('paymentstatus', 'Unpaid')
        .limit(100000)

      if (error) throw error

      const today = new Date()
      today.setHours(0, 0, 0, 0)

      const aging = {
        current: [],      // 0-30 days
        days_31_60: [],   // 31-60 days
        days_61_90: [],   // 61-90 days
        days_91_120: [],  // 91-120 days
        over_120: []      // Over 120 days
      }

      data.forEach(bill => {
        const billDate = new Date(bill.billedmonth)
        const daysDiff = Math.floor((today - billDate) / (1000 * 60 * 60 * 24))

        if (daysDiff <= 30) aging.current.push(bill)
        else if (daysDiff <= 60) aging.days_31_60.push(bill)
        else if (daysDiff <= 90) aging.days_61_90.push(bill)
        else if (daysDiff <= 120) aging.days_91_120.push(bill)
        else aging.over_120.push(bill)
      })

      const summary = {
        current: {
          count: aging.current.length,
          amount: aging.current.reduce((sum, b) => sum + parseFloat(b.totalbillamount || 0), 0)
        },
        days_31_60: {
          count: aging.days_31_60.length,
          amount: aging.days_31_60.reduce((sum, b) => sum + parseFloat(b.totalbillamount || 0), 0)
        },
        days_61_90: {
          count: aging.days_61_90.length,
          amount: aging.days_61_90.reduce((sum, b) => sum + parseFloat(b.totalbillamount || 0), 0)
        },
        days_91_120: {
          count: aging.days_91_120.length,
          amount: aging.days_91_120.reduce((sum, b) => sum + parseFloat(b.totalbillamount || 0), 0)
        },
        over_120: {
          count: aging.over_120.length,
          amount: aging.over_120.reduce((sum, b) => sum + parseFloat(b.totalbillamount || 0), 0)
        }
      }

      const totalAmount = Object.values(summary).reduce((sum, s) => sum + s.amount, 0)
      const totalCount = Object.values(summary).reduce((sum, s) => sum + s.count, 0)

      return {
        success: true,
        data: {
          summary,
          totalAmount,
          totalCount,
          details: aging
        }
      }
    } catch (error) {
      console.error('Error getting aging report:', error)
      return { success: false, error: error.message }
    }
  },

  // Customer Analysis Report
  async getCustomerAnalysis() {
    try {
      const { data, error } = await supabase
        .from('customers')
        .select('*')
        .limit(100000)

      if (error) throw error

      // Group by status
      const byStatus = {}
      data.forEach(c => {
        const status = c.status || 'Unknown'
        byStatus[status] = (byStatus[status] || 0) + 1
      })

      // Group by type
      const byType = {}
      data.forEach(c => {
        const type = c.type || 'Unknown'
        byType[type] = (byType[type] || 0) + 1
      })

      // Group by barangay
      const byBarangay = {}
      data.forEach(c => {
        const barangay = c.barangay || 'Unknown'
        byBarangay[barangay] = (byBarangay[barangay] || 0) + 1
      })

      return {
        success: true,
        data: {
          total: data.length,
          active: data.filter(c => c.status === 'Active').length,
          inactive: data.filter(c => c.status === 'Inactive').length,
          byStatus: Object.entries(byStatus).map(([status, count]) => ({ status, count })).sort((a, b) => b.count - a.count),
          byType: Object.entries(byType).map(([type, count]) => ({ type, count })).sort((a, b) => b.count - a.count),
          byBarangay: Object.entries(byBarangay).map(([barangay, count]) => ({ barangay, count })).sort((a, b) => b.count - a.count)
        }
      }
    } catch (error) {
      console.error('Error getting customer analysis:', error)
      return { success: false, error: error.message }
    }
  },
  // Get water usage report by date range
  async getWaterUsageReport(startDate, endDate) {
    try {
      const { data, error } = await supabase
        .from('bills')
        .select('billedmonth, consumption, customerid')
        .gte('billedmonth', startDate)
        .lte('billedmonth', endDate)
        .order('billedmonth', { ascending: true })
        .limit(100000)

      if (error) throw error

      // Aggregate data
      const totalConsumption = data.reduce((sum, bill) => sum + parseFloat(bill.consumption || 0), 0)
      const averageConsumption = data.length > 0 ? totalConsumption / data.length : 0

      // Group by month
      const byMonth = {}
      data.forEach(bill => {
        const month = bill.billedmonth
        if (!byMonth[month]) {
          byMonth[month] = { month, consumption: 0, count: 0 }
        }
        byMonth[month].consumption += parseFloat(bill.consumption || 0)
        byMonth[month].count++
      })

      // Group by barangay
      const byBarangay = {}
      data.forEach(bill => {
        const barangay = bill.barangay || 'Unknown'
        if (!byBarangay[barangay]) {
          byBarangay[barangay] = { barangay, consumption: 0, count: 0 }
        }
        byBarangay[barangay].consumption += parseFloat(bill.consumption || 0)
        byBarangay[barangay].count++
      })

      return {
        success: true,
        data: {
          totalConsumption,
          averageConsumption,
          billCount: data.length,
          byMonth: Object.values(byMonth),
          byBarangay: Object.values(byBarangay).sort((a, b) => b.consumption - a.consumption),
          rawData: data
        }
      }
    } catch (error) {
      console.error('Error getting water usage report:', error)
      return { success: false, error: error.message }
    }
  },

  // Get revenue report by date range
  async getRevenueReport(startDate, endDate) {
    try {
      const { data, error } = await supabase
        .from('bills')
        .select('billedmonth, totalbillamount, paymentstatus, datepaid, basicamount, surchargeamount, discountamount')
        .gte('billedmonth', startDate)
        .lte('billedmonth', endDate)
        .limit(100000)

      if (error) throw error

      // Calculate totals
      const totalBilled = data.reduce((sum, bill) => sum + parseFloat(bill.totalbillamount || 0), 0)
      const totalPaid = data
        .filter(bill => bill.paymentstatus === 'Paid')
        .reduce((sum, bill) => sum + parseFloat(bill.totalbillamount || 0), 0)
      const totalUnpaid = data
        .filter(bill => bill.paymentstatus === 'Unpaid')
        .reduce((sum, bill) => sum + parseFloat(bill.totalbillamount || 0), 0)
      const totalSurcharge = data.reduce((sum, bill) => sum + parseFloat(bill.surchargeamount || 0), 0)
      const totalDiscount = data.reduce((sum, bill) => sum + parseFloat(bill.discountamount || 0), 0)

      const paidCount = data.filter(bill => bill.paymentstatus === 'Paid').length
      const unpaidCount = data.filter(bill => bill.paymentstatus === 'Unpaid').length
      const collectionRate = data.length > 0 ? (paidCount / data.length) * 100 : 0

      // Group by month
      const byMonth = {}
      data.forEach(bill => {
        const month = bill.billedmonth
        if (!byMonth[month]) {
          byMonth[month] = { month, billed: 0, paid: 0, unpaid: 0 }
        }
        byMonth[month].billed += parseFloat(bill.totalbillamount || 0)
        if (bill.paymentstatus === 'Paid') {
          byMonth[month].paid += parseFloat(bill.totalbillamount || 0)
        } else {
          byMonth[month].unpaid += parseFloat(bill.totalbillamount || 0)
        }
      })

      // Group by barangay
      const byBarangay = {}
      data.forEach(bill => {
        const barangay = bill.barangay || 'Unknown'
        if (!byBarangay[barangay]) {
          byBarangay[barangay] = { barangay, billed: 0, paid: 0, unpaid: 0, billCount: 0 }
        }
        byBarangay[barangay].billed += parseFloat(bill.totalbillamount || 0)
        byBarangay[barangay].billCount++
        if (bill.paymentstatus === 'Paid') {
          byBarangay[barangay].paid += parseFloat(bill.totalbillamount || 0)
        } else {
          byBarangay[barangay].unpaid += parseFloat(bill.totalbillamount || 0)
        }
      })

      return {
        success: true,
        data: {
          totalBilled,
          totalPaid,
          totalUnpaid,
          totalSurcharge,
          totalDiscount,
          paidCount,
          unpaidCount,
          collectionRate,
          byMonth: Object.values(byMonth),
          byBarangay: Object.values(byBarangay).sort((a, b) => b.billed - a.billed)
        }
      }
    } catch (error) {
      console.error('Error getting revenue report:', error)
      return { success: false, error: error.message }
    }
  },

  // Get payment collection report (actual collections by date paid)
  async getCollectionReport(startDate, endDate) {
    try {
      const { data, error } = await supabase
        .from('bills')
        .select('datepaid, totalbillamount, paidby, customerid')
        .eq('paymentstatus', 'Paid')
        .gte('datepaid', startDate)
        .lte('datepaid', endDate)
        .order('datepaid', { ascending: true })
        .limit(100000)

      if (error) throw error

      const totalCollected = data.reduce((sum, bill) => sum + parseFloat(bill.totalbillamount || 0), 0)

      // Group by date
      const byDate = {}
      data.forEach(bill => {
        const date = bill.datepaid.split('T')[0]
        if (!byDate[date]) {
          byDate[date] = { date, amount: 0, count: 0 }
        }
        byDate[date].amount += parseFloat(bill.totalbillamount || 0)
        byDate[date].count++
      })

      // Group by collector
      const byCollector = {}
      data.forEach(bill => {
        const collector = bill.paidby || 'Unknown'
        if (!byCollector[collector]) {
          byCollector[collector] = { collector, amount: 0, count: 0 }
        }
        byCollector[collector].amount += parseFloat(bill.totalbillamount || 0)
        byCollector[collector].count++
      })

      return {
        success: true,
        data: {
          totalCollected,
          collectionCount: data.length,
          byDate: Object.values(byDate),
          byCollector: Object.values(byCollector).sort((a, b) => b.amount - a.amount)
        }
      }
    } catch (error) {
      console.error('Error getting collection report:', error)
      return { success: false, error: error.message }
    }
  },

  // Get top consumers
  async getTopConsumers(startDate, endDate, limit = 10) {
    try {
      const { data, error } = await supabase
        .from('bills')
        .select('customerid, consumption')
        .gte('billedmonth', startDate)
        .lte('billedmonth', endDate)
        .limit(100000)

      if (error) throw error

      // Aggregate by customer
      const byCustomer = {}
      data.forEach(bill => {
        const customerid = bill.customerid
        if (!byCustomer[customerid]) {
          byCustomer[customerid] = {
            customerid,
            totalConsumption: 0
          }
        }
        byCustomer[customerid].totalConsumption += parseFloat(bill.consumption || 0)
      })

      // Sort and get top consumers
      const topConsumers = Object.values(byCustomer)
        .sort((a, b) => b.totalConsumption - a.totalConsumption)
        .slice(0, limit)

      // Fetch customer details for top consumers
      if (topConsumers.length > 0) {
        const customerIds = topConsumers.map(c => c.customerid)
        const { data: customers, error: custError } = await supabase
          .from('customers')
          .select('customerid, name, address, barangay, meterno')
          .in('customerid', customerIds)

        if (!custError && customers) {
          topConsumers.forEach(consumer => {
            const customer = customers.find(c => c.customerid === consumer.customerid)
            if (customer) {
              consumer.customername = customer.name
              consumer.address = customer.address
              consumer.barangay = customer.barangay
              consumer.meterno = customer.meterno
            }
          })
        }
      }

      return { success: true, data: topConsumers }
    } catch (error) {
      console.error('Error getting top consumers:', error)
      return { success: false, error: error.message }
    }
  }
}
