  async getPropertiesByOwner(ownerId) {
    try {
      // Get properties for this owner
      const { data: properties, error: propError } = await supabase
        .from('rpt_properties')
        .select(`
          *,
          owner:rpt_owners(owner_id, owner_name),
          kind:rpt_property_kinds(kind_id, kind_name),
          classification:rpt_property_classifications(classification_id, classification_name)
        `)
        .eq('owner_id', ownerId)
        .order('td_number', { ascending: true })

      if (propError) throw propError
      
      // Get property IDs to fetch assessments
      const propertyIds = (properties || []).map(p => p.property_id)
      
      // Get current assessments for these properties
      const { data: assessments, error: assessError } = await supabase
        .from('rpt_current_assessments')
        .select('property_id, assessed_value, effectivity_year')
        .in('property_id', propertyIds)

      if (assessError) console.error('Error fetching assessments:', assessError)
      
      // Create a map of property_id to assessment
      const assessmentMap = (assessments || []).reduce((acc, assessment) => {
        acc[assessment.property_id] = assessment
        return acc
      }, {})
      
      // Flatten the joined data and add current assessment
      const flattenedData = (properties || []).map(prop => ({
        ...prop,
        owner_name: prop.owner?.owner_name || null,
        kind_name: prop.kind?.kind_name || null,
        classification_name: prop.classification?.classification_name || null,
        assessed_value: assessmentMap[prop.property_id]?.assessed_value || null,
        effectivity_year: assessmentMap[prop.property_id]?.effectivity_year || null
      }))
      
      return { success: true, data: flattenedData }
    } catch (error) {
      console.error('Error getting properties by owner:', error)
      return { success: false, error: error.message, data: [] }
    }
  },

