  async getAllPayments(startDate = null, endDate = null) {
    try {
      let all = []
      let from = 0
      const pageSize = 1000
      let hasMore = true

      while (hasMore) {
        let query = supabase
          .from('rpt_payments')
          .select(`
            *,
            property:rpt_properties(property_id, td_number, barangay, pin),
            owner:rpt_owners(owner_id, owner_name)
          `)
          .order('payment_date', { ascending: false })
          .range(from, from + pageSize - 1)

        if (startDate && endDate) {
          query = query.gte('payment_date', startDate).lte('payment_date', endDate)
        }

        const { data, error } = await query

        if (error) throw error

        if (data && data.length > 0) {
          all = all.concat(data)
          from += pageSize
          hasMore = data.length === pageSize
        } else {
          hasMore = false
        }
      }

      return { success: true, data: all }
    } catch (error) {
      console.error('Error getting payments:', error)
      return { success: false, error: error.message, data: [] }
    }
  },

