  async searchProperties(searchTerm) {
    try {
      const baseSelect = `
          *,
          owner:rpt_owners(owner_id, owner_name),
          kind:rpt_property_kinds(kind_id, kind_name),
          classification:rpt_property_classifications(classification_id, classification_name)
        `

      let properties = []

      if (searchTerm) {
        // 1) Search main property fields
        const { data: propsByFields, error: fieldsError } = await supabase
          .from('rpt_properties')
          .select(baseSelect)
          .or(`td_number.ilike.%${searchTerm}%,pin.ilike.%${searchTerm}%,arpn.ilike.%${searchTerm}%,barangay.ilike.%${searchTerm}%`)
          .order('td_number', { ascending: true })
          .limit(50)

        if (fieldsError) throw fieldsError

        // 2) Search owners by name, then fetch their properties
        const { data: ownersByName, error: ownersError } = await supabase
          .from('rpt_owners')
          .select('owner_id, owner_name')
          .ilike('owner_name', `%${searchTerm}%`)
          .limit(50)

        if (ownersError) throw ownersError

        let propsByOwner = []
        if (ownersByName && ownersByName.length > 0) {
          const ownerIds = ownersByName.map(o => o.owner_id)
          const { data: ownerProps, error: ownerPropsError } = await supabase
            .from('rpt_properties')
            .select(baseSelect)
            .in('owner_id', ownerIds)
            .order('td_number', { ascending: true })
            .limit(100)
          if (ownerPropsError) throw ownerPropsError
          propsByOwner = ownerProps || []
        }

        // Merge and dedupe by property_id
        const map = new Map()
        ;[...(propsByFields || []), ...propsByOwner].forEach(p => {
          map.set(p.property_id, p)
        })
        properties = Array.from(map.values())
      } else {
        // No search term: show a default subset
        const { data: defaultProps, error } = await supabase
          .from('rpt_properties')
          .select(baseSelect)
          .order('td_number', { ascending: true })
          .limit(25)

        if (error) throw error
        properties = defaultProps || []
      }
      if (properties && properties.length > 0) {
        const propertyIds = properties.map(p => p.property_id)
        
        // 1. Fetch Assessments
        let assessmentMap = {}
        const { data: assessments } = await supabase
          .from('rpt_current_assessments')
          .select('property_id, assessed_value, effectivity_year')
          .in('property_id', propertyIds)
        
        if (assessments) {
          assessmentMap = assessments.reduce((acc, curr) => {
            acc[curr.property_id] = curr
            return acc
          }, {})
        }

        // 2. Fetch Latest Payments
        let paymentMap = {}
        const { data: payments } = await supabase
          .from('rpt_payments')
          .select('property_id, year_to')
          .in('property_id', propertyIds)
        
        if (payments) {
          paymentMap = payments.reduce((acc, curr) => {
            const currentMax = acc[curr.property_id] || 0
            if (curr.year_to > currentMax) {
              acc[curr.property_id] = curr.year_to
            }
            return acc
          }, {})
        }

        const enrichedData = properties.map(prop => ({
          ...prop,
          owner_name: prop.owner?.owner_name || null,
          kind_name: prop.kind?.kind_name || null,
          classification_name: prop.classification?.classification_name || null,
          assessed_value: assessmentMap[prop.property_id]?.assessed_value || null,
          effectivity_year: assessmentMap[prop.property_id]?.effectivity_year || null,
          last_payment_year: paymentMap[prop.property_id] || null
        }))
        
        return { success: true, data: enrichedData }
      }

      return { success: true, data: [] }
    } catch (error) {
      console.error('Error searching properties:', error)
      return { success: false, error: error.message, data: [] }
    }
  },

