  async getDashboardStats() {
    try {
      // Get total properties
      const { count: totalProperties } = await supabase
        .from('rpt_properties')
        .select('*', { count: 'exact', head: true })

      // Get total owners (no status filter - rpt_owners table doesn't have status column)
      const { count: totalOwners } = await supabase
        .from('rpt_owners')
        .select('*', { count: 'exact', head: true })

      // Get current year unpaid assessments
      const currentYear = new Date().getFullYear()
      const { count: unpaidAssessments } = await supabase
        .from('rpt_assessments')
        .select('*', { count: 'exact', head: true })
        .eq('assessment_year', currentYear)
        .neq('payment_status', 'Paid')

      // Get total collections this year
      const { data: payments, error: paymentsError } = await supabase
        .from('rpt_payments')
        .select('amount_paid')
        .gte('payment_date', `${currentYear}-01-01`)
        .lte('payment_date', `${currentYear}-12-31`)

      if (paymentsError) throw paymentsError

      const totalCollections = payments?.reduce((sum, p) => sum + parseFloat(p.amount_paid || 0), 0) || 0

      return {
        success: true,
        data: {
          totalProperties: totalProperties || 0,
          totalOwners: totalOwners || 0,
          unpaidAssessments: unpaidAssessments || 0,
          totalCollections,
          currentYear
        }
      }
    } catch (error) {
      console.error('Error getting dashboard stats:', error)
      return { success: false, error: error.message }
    }
  },

