  // Calculate tax based on property class and assessed value
  calculateTax(assessedValue, propertyClass, taxRates) {
    const rate = taxRates.find(r => r.property_class === propertyClass)
    
    if (!rate) {
      return {
        basic_tax: 0,
        sef_tax: 0,
        total_tax: 0
      }
    }

    const basic_tax = assessedValue * rate.basic_rate
    const sef_tax = assessedValue * rate.sef_rate
    const total_tax = basic_tax + sef_tax

    return {
      basic_tax: parseFloat(basic_tax.toFixed(2)),
      sef_tax: parseFloat(sef_tax.toFixed(2)),
      total_tax: parseFloat(total_tax.toFixed(2)),
      basic_rate: rate.basic_rate,
      sef_rate: rate.sef_rate
    }
  },

