import React, { useState, useEffect } from 'react';
import {
  Box,
  Paper,
  Typography,
  IconButton,
  Avatar,
  Badge,
  List,
  ListItem,
  ListItemAvatar,
  ListItemText,
  TextField,
  InputAdornment,
  Fab,
  Tooltip
} from '@mui/material';
import {
  Chat as ChatIcon,
  Close,
  Search,
  ExpandMore,
  ExpandLess
} from '@mui/icons-material';

const ChatFloatingPanel = ({ 
  currentUser, 
  onlineUsers, 
  allUsers, 
  unreadCounts, 
  onUserClick 
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Merge all users with online status
  const displayUsers = allUsers
    .filter(u => u.userid !== currentUser.userid) // Exclude self
    .map(u => ({
      ...u,
      isOnline: onlineUsers.some(ou => ou.userid === u.userid),
      unread: unreadCounts[u.userid] || 0
    }))
    .sort((a, b) => {
      // Sort by online status first, then name
      if (a.isOnline === b.isOnline) return a.firstname.localeCompare(b.firstname);
      return a.isOnline ? -1 : 1;
    })
    .filter(u => 
      searchTerm === '' || 
      `${u.firstname} ${u.lastname}`.toLowerCase().includes(searchTerm.toLowerCase()) ||
      u.department?.toLowerCase().includes(searchTerm.toLowerCase())
    );

  const totalUnread = Object.values(unreadCounts).reduce((a, b) => a + b, 0);

  if (!isOpen) {
    return (
      <Tooltip title="Online Users / Chat">
        <Fab 
          color="primary" 
          aria-label="chat"
          onClick={() => setIsOpen(true)}
          sx={{
            position: 'fixed',
            bottom: 24,
            left: 24,
            zIndex: 2147483000
          }}
        >
          <Badge badgeContent={totalUnread} color="error">
            <ChatIcon />
          </Badge>
        </Fab>
      </Tooltip>
    );
  }

  return (
    <Paper
      elevation={5}
      sx={{
        position: 'fixed',
        bottom: 0,
        left: 20,
        width: 280,
        height: 450,
        display: 'flex',
        flexDirection: 'column',
        borderTopLeftRadius: 12,
        borderTopRightRadius: 12,
        overflow: 'hidden',
        zIndex: 2147483000
      }}
    >
      {/* Header */}
      <Box 
        sx={{ 
          p: 1.5, 
          bgcolor: 'primary.main', 
          color: 'white',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          cursor: 'pointer'
        }}
        onClick={() => setIsOpen(false)}
      >
        <Box display="flex" alignItems="center" gap={1}>
          <ChatIcon fontSize="small" />
          <Typography variant="subtitle1" fontWeight="bold">Messaging</Typography>
          {totalUnread > 0 && (
            <Chip 
              label={totalUnread} 
              size="small" 
              color="error" 
              sx={{ height: 20, minWidth: 20 }} 
            />
          )}
        </Box>
        <IconButton size="small" onClick={(e) => { e.stopPropagation(); setIsOpen(false); }} sx={{ color: 'white' }}>
          <ExpandMore />
        </IconButton>
      </Box>

      {/* Search */}
      <Box sx={{ p: 1, borderBottom: '1px solid #eee' }}>
        <TextField
          fullWidth
          size="small"
          placeholder="Search users..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          InputProps={{
            startAdornment: <InputAdornment position="start"><Search fontSize="small" /></InputAdornment>
          }}
        />
      </Box>

      {/* User List */}
      <List sx={{ flex: 1, overflowY: 'auto', p: 0 }}>
        {displayUsers.length === 0 ? (
          <Box p={2} textAlign="center">
            <Typography variant="body2" color="text.secondary">No users found.</Typography>
          </Box>
        ) : (
          displayUsers.map(user => (
            <ListItem 
              key={user.userid} 
              button 
              onClick={() => onUserClick(user)}
              sx={{ 
                borderBottom: '1px solid #f5f5f5',
                bgcolor: user.unread > 0 ? '#f0f7ff' : 'transparent'
              }}
            >
              <ListItemAvatar>
                <Badge
                  overlap="circular"
                  anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
                  variant="dot"
                  color={user.isOnline ? "success" : "default"}
                  sx={{ '& .MuiBadge-badge': { border: '2px solid white' } }}
                >
                  <Avatar sx={{ bgcolor: 'primary.light' }}>
                    {user.firstname?.[0]}{user.lastname?.[0]}
                  </Avatar>
                </Badge>
              </ListItemAvatar>
              <ListItemText 
                primary={
                  <Box display="flex" justifyContent="space-between">
                    <Typography variant="body2" fontWeight={user.unread > 0 ? 'bold' : 'normal'}>
                      {user.firstname} {user.lastname}
                    </Typography>
                    {user.unread > 0 && (
                      <Badge badgeContent={user.unread} color="primary" />
                    )}
                  </Box>
                }
                secondary={
                  <Typography variant="caption" color="text.secondary" noWrap>
                    {user.department || user.position || 'User'}
                  </Typography>
                }
              />
            </ListItem>
          ))
        )}
      </List>
    </Paper>
  );
};

// Need Chip import
import { Chip } from '@mui/material';

export default ChatFloatingPanel;
