import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { authService } from '../authService';
import { Box, Button, Container, Paper, TextField, Typography, Alert, IconButton, InputAdornment, CircularProgress, Avatar, Stack, Link, Divider, Fade } from '@mui/material';
import { Security, Email, Lock, Visibility, VisibilityOff, HelpOutline, PrivacyTip, Description, Facebook, Twitter, Google, LinkedIn, Apartment } from '@mui/icons-material';

const Login = ({ onLoginSuccess }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const navigate = useNavigate();
  

  useEffect(() => {
    document.title = 'Sign In - LGU Concepcion Systems Portal';
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    if (!email || !password) {
      setError('Please fill in all fields');
      setLoading(false);
      return;
    }

    try {
      const result = await authService.login(email, password);
      
      if (result.success) {
        authService.setUserSession(result.user);
        if (onLoginSuccess) {
          onLoginSuccess();
        }
        navigate('/portal', { replace: true });
      } else {
        setError(result.error);
      }
    } catch (err) {
      setError('An unexpected error occurred');
    } finally {
      setLoading(false);
    }
  };

  

  return (
    <Box sx={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', bgcolor: '#f6f7fb', px: 2 }}>
      <Container maxWidth="md">
        <Fade in={true} timeout={600}>
          <Paper sx={{ display: 'flex', overflow: 'hidden', borderRadius: 4, boxShadow: '0 20px 40px rgba(0,0,0,0.12)' }}>
            <Box sx={{ flex: 1, bgcolor: 'white', p: { xs: 3, md: 4 } }}>
              <Stack spacing={3}>
                <Box>
                  <Typography variant="overline" sx={{ letterSpacing: 1.2 }} color="text.secondary">Welcome to</Typography>
                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                    <Avatar sx={{ bgcolor: 'error.main', width: 32, height: 32 }}>
                      <Security fontSize="small" />
                    </Avatar>
                    <Typography variant="h6" fontWeight={800} color="error.main">LGU Concepcion</Typography>
                  </Box>
                  <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>Log in to access your municipal systems and updates.</Typography>
                </Box>
                {error && (
                  <Alert severity="error" onClose={() => setError('')} sx={{ borderRadius: 2 }}>
                    {error}
                  </Alert>
                )}
                <form onSubmit={handleSubmit}>
                  <Stack spacing={2.5}>
                    <TextField
                      fullWidth
                      placeholder="Username or email"
                      variant="outlined"
                      type="email"
                      value={email}
                      onChange={(e) => setEmail(e.target.value)}
                      disabled={loading}
                      required
                      InputProps={{
                        startAdornment: (
                          <InputAdornment position="start">
                            <Email color="action" fontSize="small" />
                          </InputAdornment>
                        ),
                        sx: { borderRadius: 3 }
                      }}
                    />
                    <TextField
                      fullWidth
                      placeholder="Password"
                      variant="outlined"
                      type={showPassword ? 'text' : 'password'}
                      value={password}
                      onChange={(e) => setPassword(e.target.value)}
                      disabled={loading}
                      required
                      InputProps={{
                        startAdornment: (
                          <InputAdornment position="start">
                            <Lock color="action" fontSize="small" />
                          </InputAdornment>
                        ),
                        endAdornment: (
                          <InputAdornment position="end">
                            <IconButton onClick={() => setShowPassword(!showPassword)} edge="end" size="small">
                              {showPassword ? <VisibilityOff fontSize="small" /> : <Visibility fontSize="small" />}
                            </IconButton>
                          </InputAdornment>
                        ),
                        sx: { borderRadius: 3 }
                      }}
                    />
                    <Button
                      fullWidth
                      size="large"
                      type="submit"
                      variant="contained"
                      disabled={loading}
                      sx={{
                        py: 1.3,
                        fontSize: '0.95rem',
                        fontWeight: 700,
                        borderRadius: 3,
                        background: 'linear-gradient(135deg, #ff512f 0%, #f09819 100%)',
                        boxShadow: '0 8px 16px rgba(240, 152, 25, 0.35)',
                        '&:hover': { filter: 'brightness(1.05)' }
                      }}
                    >
                      {loading ? <CircularProgress size={24} color="inherit" /> : 'Sign In'}
                    </Button>
                  </Stack>
                </form>
                <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <Link href="#" underline="hover" color="primary" fontWeight={600}>Sign Up Now</Link>
                  <Link href="#" underline="hover" color="text.secondary">Forgot password?</Link>
                </Box>
                <Divider />
                <Box>
                  <Typography variant="caption" color="text.secondary">Continue with social media</Typography>
                  <Stack direction="row" spacing={1.5} sx={{ mt: 1.5 }}>
                    <IconButton size="small" color="primary"><Facebook /></IconButton>
                    <IconButton size="small" color="primary"><Twitter /></IconButton>
                    <IconButton size="small" color="primary"><Google /></IconButton>
                    <IconButton size="small" color="primary"><LinkedIn /></IconButton>
                  </Stack>
                </Box>
                <Typography variant="caption" display="block" color="text.disabled">© 2024 LGU Concepcion, Romblon</Typography>
              </Stack>
            </Box>
            <Box sx={{ flex: 1, display: { xs: 'none', md: 'block' }, position: 'relative', minHeight: 480, backgroundImage: 'url(https://images.unsplash.com/photo-1506806732259-39c2d0268443?q=80&w=2072&auto=format&fit=crop)', backgroundSize: 'cover', backgroundPosition: 'center' }}>
              <Box sx={{ position: 'absolute', inset: 0, background: 'linear-gradient(135deg, rgba(255, 82, 82, 0.85) 0%, rgba(255, 94, 0, 0.75) 100%)' }} />
              <Box sx={{ position: 'relative', zIndex: 1, height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center', textAlign: 'center', color: 'white', p: 4 }}>
                <Stack spacing={1} alignItems="center">
                  <Avatar sx={{ bgcolor: 'rgba(255,255,255,0.2)', color: 'white', width: 56, height: 56 }}>
                    <Apartment />
                  </Avatar>
                  <Typography variant="h4" fontWeight={800}>LGU Concepcion</Typography>
                  <Typography variant="subtitle1" sx={{ opacity: 0.95 }}>Systems Portal</Typography>
                  <Typography variant="body2" sx={{ maxWidth: 360, opacity: 0.9 }}>Access consolidated municipal services and dashboards with secure authentication and modern UI.</Typography>
                </Stack>
              </Box>
            </Box>
          </Paper>
        </Fade>
      </Container>
    </Box>
  );
};

export default Login;
